pub(crate) fn pt_brief(mut t: &mut String, nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells) -> i32 {
    // The brief of the Model (see the head of this file): every node but the root, in id order.
    let n: i32 = node_count(nodes);
    let mut i: i32 = 1;
    let mut k: i32 = 0;
    let mut kind: i32 = 0;
    let mut s: i32 = 0;
    while i < n {
        kind = node_kind(nodes, i);
        if kind == nk_paragraph() {
            crate::port::text_cp(t, 80);
            crate::port::text_i32(t, node_region_count(nodes, i));
            crate::port::text_cp(t, 58);
        }
        if kind == nk_text() {
            crate::port::text_cp(t, 84);
            crate::port::text_cp(t, 58);
        }
        if kind == nk_note() {
            crate::port::text_cp(t, 78);
            crate::port::text_i32(t, node_sub(nodes, i));
        }
        if kind == nk_break() {
            crate::port::text_cp(t, 66);
            crate::port::text_i32(t, node_sub(nodes, i));
        }
        if (kind == nk_paragraph()) || (kind == nk_text()) {
            s = node_text_start(nodes, i);
            k = 0;
            while k < node_text_len(nodes, i) {
                crate::port::text_cp(t, text_at(text, s + k));
                k += 1;
            }
        }
        crate::port::text_cp(t, 59);
        i += 1;
    }
    return 0;
}
#[test]
fn test_a_gap_and_an_indent_end_a_paragraph() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ord: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let raw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    let t3: &mut String = &mut crate::port::new_text();
    let t4: &mut String = &mut crate::port::new_text();
    // A vertical gap above 1.5 times the median: five lines, a tight run of three, a jump, two.
    pt_line(wd, ln, et, &crate::testport::text_blob("alpha beta")[..], 1, 7200, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("gamma delta")[..], 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("epsilon")[..], 1, 7200, 13000, 30000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("zeta eta")[..], 1, 7200, 15400, 50000, 16600, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("theta")[..], 1, 7200, 16900, 20000, 18100, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "gap: well formed");
    pt_brief(t1, nodes, regions, text);
    crate::testport::assert_text(t1, "P1:alpha beta gamma delta epsilon;P1:zeta eta theta;", "a gap of 12 pt after lines 3 pt apart starts a paragraph");
    // An indent: more than half the size, from a line at the margin. The first line of a paragraph is
    // indented, the rest are not: a LESS indented line goes on (a hanging or ordinary paragraph).
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("one two")[..], 1, 9600, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("three four")[..], 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("five")[..], 1, 7200, 13000, 30000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("six seven")[..], 1, 9600, 14500, 50000, 15700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("eight")[..], 1, 7200, 16000, 20000, 17200, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "indent: well formed");
    pt_brief(t2, nodes, regions, text);
    crate::testport::assert_text(t2, "P1:one two three four five;P1:six seven eight;", "an indented line after one at the margin starts a paragraph");
    // Centred lines start anywhere: a line that does not start at the page's margin is not an indent. The
    // first line is at the margin (and ends the first paragraph with its gap), the three centred lines go on.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("left")[..], 1, 7200, 10000, 20000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mid a")[..], 1, 9000, 13000, 40000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mid bb")[..], 1, 11000, 14500, 38000, 15700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mid c")[..], 1, 10000, 16000, 39000, 17200, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "centred: well formed");
    pt_brief(t3, nodes, regions, text);
    crate::testport::assert_text(t3, "P1:left;P1:mid a mid bb mid c;", "centred lines are one paragraph");
    // Lines on one row (two columns, a table row) do not follow one another: the second is not below the first.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("left col")[..], 1, 7200, 10000, 25000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("right col")[..], 1, 30000, 10000, 50000, 11200, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "row: well formed");
    pt_brief(t4, nodes, regions, text);
    crate::testport::assert_text(t4, "P1:left col;P1:right col;", "two lines on one row are two paragraphs");
}
