pub(crate) fn pt_bold_words(mut wd: &mut crate::port::Cells, w0: i32, from: i32, to: i32) -> i32 {
    // Words from..to (counted from the word w0, a line's first) are bold (style bit 1).
    let mut k: i32 = from;
    while k < to {
        wd_set(wd, w0 + k, wf_style(), 1);
        k += 1;
    }
    return 0;
}
