    pt_cline(wd, ln, et, &crate::testport::text_blob("C1.")[..], 1, 33000, 21000, 1200, 1000);
    pt_cline(wd, ln, et, &crate::testport::text_blob("D1.")[..], 1, 45000, 21000, 1200, 1000);
