pub(crate) fn pt_find(nodes: &mut crate::port::Cells, kind: i32, after: i32) -> i32 {
    // The first node of that kind with an index above `after`, -1 for none.
    let n: i32 = node_count(nodes);
    let mut i: i32 = after + 1;
    while i < n {
        if node_kind(nodes, i) == kind {
            return i;
        }
        i += 1;
    }
    return -1;
}
#[test]
fn test_a_drop_initial_joins_its_first_word_and_the_paragraph_is_one() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ord: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let raw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    let t3: &mut String = &mut crate::port::new_text();
    // An `O` 36 pt on 10 pt text: its cap top is the first line's (within half a size), its baseline in line 2's band,
    // lines 1 and 2 start after it, line 3 back at its start edge. One paragraph, `Once upon ...`, the initial an
    // inline `initial` (a drop of two lines) holding `O`, then the rest as text; justified, since lines 1 and 2 count
    // from the initial's edge. Without a locale the join is flagged: `O` is a word in some language.
    pt_line(wd, ln, et, &crate::testport::text_blob("O")[..], 1, 7200, 10200, 9400, 13000, 0, 0, 3600);
    pt_line(wd, ln, et, &crate::testport::text_blob("nce upon a time")[..], 1, 9800, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("there was a mill")[..], 1, 9800, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("that nobody saw")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("the end of it")[..], 1, 7200, 14500, 30000, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "drop: well formed");
    pt_brief(t1, nodes, regions, text);
    crate::testport::assert_text(t1, "P1:Once upon a time there was a mill that nobody saw the end of it;;T:O;T:nce upon a time there was a mill that nobody saw the end of it;", "a drop initial: one paragraph, joined, no space");
    let ini: i32 = pt_find(nodes, nk_initial(), 0);
    crate::testport::assert_eq(node_sub(nodes, ini), ifm_drop(), "the form is drop");
    crate::testport::assert_eq(node_aux(nodes, ini), 2, "of two lines");
    crate::testport::assert_eq(node_flags(nodes, ini), fl_low_conf(), "and the join is in doubt");
    crate::testport::assert_eq(node_sub(nodes, 1), al_justify(), "justified: lines 1 and 2 start at the initial's edge");
    // A letter divider: a big letter with nothing wrapping it. The line below starts at the same edge, not after the
    // letter, so it is no initial and stays a block of its own.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("A")[..], 1, 7200, 10000, 9500, 13400, 0, 0, 3000);
    pt_line(wd, ln, et, &crate::testport::text_blob("Aardvark an animal here")[..], 1, 7200, 14000, 50000, 15200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("that digs at night")[..], 1, 7200, 15500, 50000, 16700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "divider: well formed");
    pt_brief(t2, nodes, regions, text);
    crate::testport::assert_text(t2, "P1:A;P1:Aardvark an animal here that digs at night;", "a letter divider is no initial");
    crate::testport::assert_eq(pt_find(nodes, nk_initial(), 0), -1, "no initial inline");
    // A margin initial: it hangs left of the column (its end edge before the lines' start), the lines are not
    // indented, and there are lines after its two.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("Q")[..], 1, 3000, 10200, 6200, 13000, 0, 0, 3600);
    pt_line(wd, ln, et, &crate::testport::text_blob("uiet nights in town")[..], 1, 7200, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("were rare that year")[..], 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("and the lamps burned")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("low until dawn")[..], 1, 7200, 14500, 40000, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "margin: well formed");
    pt_brief(t3, nodes, regions, text);
    crate::testport::assert_text(t3, "P1:Quiet nights in town were rare that year and the lamps burned low until dawn;;T:Q;T:uiet nights in town were rare that year and the lamps burned low until dawn;", "a margin initial");
    let ini2: i32 = pt_find(nodes, nk_initial(), 0);
    crate::testport::assert_eq(node_sub(nodes, ini2), ifm_margin(), "the form is margin");
    crate::testport::assert_eq(node_aux(nodes, ini2), 2, "of two lines");
    crate::testport::assert_eq(node_flags(nodes, ini2), 0, "a `Q` is no word: the join is sure");
}
#[test]
fn test_a_right_to_left_initial_is_mirrored() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ord: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let raw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    // The initial at the right (a start edge of -x1), the first two lines to its left, the third back at the right edge.
    pt_line(wd, ln, et, &crate::testport::text_blob("B")[..], 1, 43000, 10200, 45000, 13000, 0, 1, 3600);
    pt_line(wd, ln, et, &crate::testport::text_blob("ab cd ef gh")[..], 1, 7200, 10000, 42500, 11200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ij kl mn op")[..], 1, 7200, 11500, 42500, 12700, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("qr st uv wx")[..], 1, 7200, 13000, 45000, 14200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("yz ab cd ef")[..], 1, 7200, 14500, 45000, 15700, 0, 1, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "rtl: well formed");
    pt_brief(t1, nodes, regions, text);
    crate::testport::assert_text(t1, "P1:Bab cd ef gh ij kl mn op qr st uv wx yz ab cd ef;;T:B;T:ab cd ef gh ij kl mn op qr st uv wx yz ab cd ef;", "a right-to-left initial");
    let ini3: i32 = pt_find(nodes, nk_initial(), 0);
    crate::testport::assert_eq(node_sub(nodes, ini3), ifm_drop(), "a drop");
}
#[test]
fn test_a_paragraphs_alignment_is_measured_against_its_fragment() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ord: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let raw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // Justified: three lines flush at both edges of the fragment, the last short.
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 7200, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 7200, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 7200, 14500, 20000, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "justify: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_justify(), "justify");
    // Left-aligned: a ragged end edge, every start at the edge (the fragment's box is the widest line's).
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 7200, 10000, 45000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 7200, 11500, 42000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 7200, 14500, 30000, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "start: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_start(), "start");
    // Right-aligned: a ragged start edge, every end at the edge.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 12200, 10000, 50000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 15200, 11500, 50000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 33000, 14500, 50000, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "end: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_end(), "end");
    // Centred: equal gaps either side, and the lines differ in width.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 17200, 10000, 40000, 11200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 12200, 11500, 45000, 12700, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 0, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 25000, 14500, 32200, 15700, 0, 0, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "center: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_center(), "center");
    // Right to left, every line ending at the box's LEFT edge (a right-to-left line's end): LOGICALLY `end`, though these
    // are the lines the left-to-right case calls `start`; and the same page set flush right is `start`.
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 7200, 10000, 45000, 11200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 7200, 11500, 42000, 12700, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 7200, 14500, 30000, 15700, 0, 1, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "rtl end: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_end(), "right-to-left, flush left: end");
    pt_clear(wd, ln, et);
    pt_line(wd, ln, et, &crate::testport::text_blob("aa bb cc dd")[..], 1, 12200, 10000, 50000, 11200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ee ff gg hh")[..], 1, 15200, 11500, 50000, 12700, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("ii jj kk ll")[..], 1, 7200, 13000, 50000, 14200, 0, 1, 1000);
    pt_line(wd, ln, et, &crate::testport::text_blob("mm nn")[..], 1, 33000, 14500, 50000, 15700, 0, 1, 1000);
    crate::testport::assert_eq(pt_run(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "rtl start: well formed");
    crate::testport::assert_eq(node_sub(nodes, 1), al_start(), "right-to-left, flush right: start");
}
#[test]
fn test_ocr_size_jitter_does_not_split_wrapped_prose() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t: &mut String = &mut crate::port::new_text();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut w: i32 = 0;
    pt_line(wd, ln, et, &crate::testport::text_blob("These scanned words continue on")[..], 1, 7200, 10000, 50000, 11200, 0, 0, 1200);
    pt_line(wd, ln, et, &crate::testport::text_blob("the next line of the paragraph.")[..], 1, 7200, 11500, 50000, 12700, 0, 0, 1320);
    while w < wd_count(wd) {
        wd_set(wd, w, wf_src(), sr_ocr());
        w += 1;
    }
    ln_set(ln, 0, lf_src(), sr_ocr());
    ln_set(ln, 1, lf_src(), sr_ocr());
    pt_run(wd, ln, et, 1, nodes, &mut crate::port::Cells::new(), regions, text, &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), &mut crate::port::Cells::new());
    pt_brief(t, nodes, regions, text);
    crate::testport::assert_text(t, "P1:These scanned words continue on the next line of the paragraph.;", "OCR x-height varies between wrapped lines");
}
